CREATE TABLE business_records (
    id BIGINT NOT NULL AUTO_INCREMENT,
    module VARCHAR(32) NOT NULL,
    type VARCHAR(64) NOT NULL,
    record_number VARCHAR(64) NOT NULL,
    party_name VARCHAR(160) NOT NULL,
    party_email VARCHAR(160),
    party_phone VARCHAR(32),
    party_city VARCHAR(120),
    category VARCHAR(80),
    status VARCHAR(64) NOT NULL,
    secondary_status VARCHAR(64),
    amount DECIMAL(14, 2) NOT NULL DEFAULT 0,
    balance_amount DECIMAL(14, 2) NOT NULL DEFAULT 0,
    record_date DATE NOT NULL,
    due_date DATE,
    reference_number VARCHAR(64),
    payment_mode VARCHAR(64),
    owner_name VARCHAR(120),
    notes TEXT,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_business_records_record_number (record_number),
    INDEX idx_business_records_module_type (module, type),
    INDEX idx_business_records_status (status),
    INDEX idx_business_records_record_date (record_date),
    INDEX idx_business_records_party_name (party_name)
);

